// Hardened Express application
// Demonstrates error handling, input validation, and security best practices.

const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');

const app = express();

// --- Security & parsing middleware ---
app.disable('x-powered-by');                 // Don't advertise Express
app.use(helmet());                           // Secure HTTP headers
app.use(express.json({ limit: '10kb' }));    // Limit body size to prevent DoS

// Rate limit all requests
app.use(
  rateLimit({
    windowMs: 15 * 60 * 1000, // 15 minutes
    max: 100,                 // limit each IP to 100 requests/window
    standardHeaders: true,
    legacyHeaders: false,
  })
);

// --- In-memory data (replace with a real data source) ---
const users = [
  { id: 1, name: 'Alice', email: 'alice@example.com' },
  { id: 2, name: 'Bob', email: 'bob@example.com' },
];

// --- Routes ---
app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

app.get('/users', (req, res) => {
  res.json(users);
});

// Example of a validated parameterized route
app.get('/users/:id', (req, res, next) => {
  try {
    const id = Number(req.params.id);

    // Input validation: must be a positive integer
    if (!Number.isInteger(id) || id <= 0) {
      return res.status(400).json({ error: 'Invalid user id' });
    }

    const user = users.find((u) => u.id === id);
    if (!user) {
      return res.status(404).json({ error: 'User not found' });
    }

    res.json(user);
  } catch (err) {
    next(err); // forward to centralized error handler
  }
});

// --- 404 handler (must come after routes) ---
app.use((req, res) => {
  res.status(404).json({ error: 'Not found' });
});

// --- Centralized error handler ---
// eslint-disable-next-line no-unused-vars
app.use((err, req, res, next) => {
  // Log full error server-side, never leak details to the client
  console.error(err.stack || err);
  res.status(err.status || 500).json({ error: 'Internal server error' });
});

// --- Server startup ---
const PORT = process.env.PORT || 3000;
const server = app.listen(PORT, () => {
  console.log(`Server running on port ${PORT}`);
});

// --- Graceful handling of process-level errors ---
process.on('unhandledRejection', (reason) => {
  console.error('Unhandled rejection:', reason);
});

process.on('uncaughtException', (err) => {
  console.error('Uncaught exception:', err);
  server.close(() => process.exit(1));
});

module.exports = app;

