// Hardened version of app.js demonstrating error handling,
// input validation, and security best practices.

const express = require('express');
const helmet = require('helmet'); // npm i helmet
const { param, query, validationResult } = require('express-validator'); // npm i express-validator

const app = express();

// --- Security & parsing middleware ---
app.use(helmet()); // sensible security headers (CSP, HSTS, X-Frame-Options, etc.)
app.use(express.json({ limit: '10kb' })); // cap body size to mitigate DoS
app.use(express.urlencoded({ extended: false, limit: '10kb' }));
app.disable('x-powered-by'); // don't advertise Express

// --- Helper to surface validation errors consistently ---
function handleValidation(req, res, next) {
  const errors = validationResult(req);
  if (!errors.isEmpty()) {
    return res.status(400).json({ error: 'Invalid input', details: errors.array() });
  }
  next();
}

// In-memory sample data (replace with a real data layer later)
const USERS = [
  { id: 1, name: 'Alice', email: 'alice@example.com' },
  { id: 2, name: 'Bob', email: 'bob@example.com' },
];

// --- Routes ---
app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

app.get(
  '/users',
  // Validate optional query params instead of trusting them blindly
  [
    query('limit').optional().isInt({ min: 1, max: 100 }).toInt(),
    query('offset').optional().isInt({ min: 0 }).toInt(),
  ],
  handleValidation,
  (req, res, next) => {
    try {
      const offset = req.query.offset ?? 0;
      const limit = req.query.limit ?? USERS.length;
      // Avoid leaking unnecessary fields (e.g., email) by default
      const page = USERS.slice(offset, offset + limit).map(({ id, name }) => ({ id, name }));
      res.json(page);
    } catch (err) {
      next(err); // delegate to centralized error handler
    }
  }
);

app.get(
  '/users/:id',
  [param('id').isInt({ min: 1 }).toInt()],
  handleValidation,
  (req, res, next) => {
    try {
      const user = USERS.find((u) => u.id === req.params.id);
      if (!user) {
        return res.status(404).json({ error: 'User not found' });
      }
      res.json({ id: user.id, name: user.name });
    } catch (err) {
      next(err);
    }
  }
);

// --- 404 handler (after all routes) ---
app.use((req, res) => {
  res.status(404).json({ error: 'Not found' });
});

// --- Centralized error handler (must have 4 args) ---
// eslint-disable-next-line no-unused-vars
app.use((err, req, res, next) => {
  // Log full detail server-side, but never leak stack traces to clients
  console.error(err);
  res.status(err.status || 500).json({ error: 'Internal server error' });
});

// --- Start server only when run directly ---
let server;
if (require.main === module) {
  const PORT = process.env.PORT || 3000;
  server = app.listen(PORT, () => {
    console.log(`Server running on port ${PORT}`);
  });

  // Graceful shutdown
  const shutdown = (signal) => {
    console.log(`Received ${signal}, shutting down gracefully...`);
    server.close(() => process.exit(0));
    // Force-exit if shutdown hangs
    setTimeout(() => process.exit(1), 10_000).unref();
  };
  process.on('SIGTERM', () => shutdown('SIGTERM'));
  process.on('SIGINT', () => shutdown('SIGINT'));

  // Last-resort safety nets
  process.on('unhandledRejection', (reason) => {
    console.error('Unhandled promise rejection:', reason);
  });
  process.on('uncaughtException', (err) => {
    console.error('Uncaught exception:', err);
    process.exit(1);
  });
}

module.exports = app;

